// Define a type alias for the Matrix
type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Extract the number of rows and columns from the shape
    let r = shape[0] as usize; // Number of rows
    let c = shape[1] as usize; // Number of columns

    // Initialize the matrix with the appropriate dimensions
    let mut matrix: Matrix<i8> = vec![vec![0; c]; r];

    // Check if the length of the array matches the number of rows or columns
    if a.len() == r {
        // Treat `a` as a column vector
        for i in 0..r {
            for j in 0..c {
                matrix[i][j] = a[i]; // Replicate the i-th element across the row
            }
        }
    } else if a.len() == c {
        // Treat `a` as a row vector
        for i in 0..r {
            for j in 0..c {
                matrix[i][j] = a[j]; // Replicate the j-th element across the column
            }
        }
    } else {
        // This case should not happen due to the problem's assumptions
        panic!("The length of the array must match either R or C.");
    }

    matrix
}

// Example usage
fn main() {
    let a = vec![1, 2, 3];
    let shape = vec![3, 2]; // 3 rows and 2 columns
    let result = broadcast(a, shape);
    
    for row in result {
        println!("{:?}", row);
    }
}